package com.example.data.supabase

import android.util.Log
import com.example.BuildConfig
import okhttp3.Interceptor
import okhttp3.OkHttpClient
import okhttp3.logging.HttpLoggingInterceptor
import retrofit2.Retrofit
import retrofit2.converter.moshi.MoshiConverterFactory
import java.util.concurrent.TimeUnit

object SupabaseClient {
    private const val TAG = "SupabaseClient"

    // Reads from BuildConfig (generated by secrets-gradle-plugin via .env)
    val supabaseUrl: String by lazy {
        try {
            val field = BuildConfig::class.java.getField("SUPABASE_URL")
            (field.get(null) as? String)?.takeIf { it.isNotBlank() && it.startsWith("http") }
                ?: "https://default.supabase.co"
        } catch (e: Exception) {
            "https://default.supabase.co"
        }
    }

    val supabaseAnonKey: String by lazy {
        try {
            val field = BuildConfig::class.java.getField("SUPABASE_ANON_KEY")
            (field.get(null) as? String)?.takeIf { it.isNotBlank() } ?: "mock-anon-key"
        } catch (e: Exception) {
            "mock-anon-key"
        }
    }

    val isConfigured: Boolean
        get() = supabaseUrl != "https://default.supabase.co" && supabaseAnonKey != "mock-anon-key"

    private val authInterceptor = Interceptor { chain ->
        val original = chain.request()
        val requestBuilder = original.newBuilder()
            .header("apikey", supabaseAnonKey)
            .header("Authorization", "Bearer $supabaseAnonKey")
            .header("Content-Type", "application/json")
        chain.proceed(requestBuilder.build())
    }

    private val okHttpClient: OkHttpClient by lazy {
        OkHttpClient.Builder()
            .addInterceptor(authInterceptor)
            .addInterceptor(HttpLoggingInterceptor().apply {
                level = HttpLoggingInterceptor.Level.BODY
            })
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(15, TimeUnit.SECONDS)
            .build()
    }

    val apiService: SupabaseApiService by lazy {
        val baseUrl = if (supabaseUrl.endsWith("/")) supabaseUrl else "$supabaseUrl/"
        Retrofit.Builder()
            .baseUrl(baseUrl)
            .client(okHttpClient)
            .addConverterFactory(MoshiConverterFactory.create())
            .build()
            .create(SupabaseApiService::class.java)
    }
}
